Repair the following GNU C++ code so that it correctly solves the programming problem. The code reads and writes I/O from the console. Your repaired code should implement the problem correctly, meaning that it should produce the correct output for any valid input.
Print your repaired code and also the confidence score you give to your repair. The confidence score should be a number between 0 and 1. The format of the output should be:
<repaired_code>
<your_repaired_code>
</repaired_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the problem description:
<problem_description>
As behooves any intelligent schoolboy, Kevin Sun is studying psycowlogy, cowculus, and cryptcowgraphy at the Bovinia State University (BGU) under Farmer Ivan. During his Mathematics of Olympiads (MoO) class, Kevin was confronted with a weird functional equation and needs your help. For two fixed integers k and p, where p is an odd prime number, the functional equation states that  for some function . (This equation should hold for any integer x in the range 0 to p - 1, inclusive.)It turns out that f can actually be many different functions. Instead of finding a solution, Kevin wants you to count the number of distinct functions f that satisfy this equation. Since the answer may be very large, you should print your result modulo 109 + 7.
</problem_description>

Here is the GNU C++ code you have to repair:
<original_code>
#include <iostream>
#include <vector>
#include <cmath>
#include <algorithm>
#include <cctype>
#include <iomanip>
#include <queue>
#include <stack>
#include <set>
#include <map>
#include <climits>
using namespace std;

using i64 = long long;
using u64 = unsigned long long;
using f80 = long double;
using pii = pair<int, int>;
using vi = vector<int>;
using vii = vector<pii>;
using pll = pair<i64, i64>;

constexpr int MOD = 1000000007;
constexpr int INF = 1000000000;
constexpr i64 LINF = 1000000000000000000LL;
constexpr f80 PI = 2 * acos(0.0);
constexpr int MAX_M = 50;
constexpr int MAX_N = 1000007;

i64 fast_pow(i64 base, i64 exp, i64 mod) {
    i64 res = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) res = (res * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return res;
}

i64 custom_pow(i64 base, i64 exp, i64 mod) {
    if (exp == 0) return 1 % mod;
    if (exp & 1) return (base * custom_pow(base, exp - 1, mod)) % mod;
    i64 half = custom_pow(base, exp >> 1, mod);
    return (half * half) % mod;
}

int n, k;
int perm[MAX_N];
bool marked[MAX_N];

void run() {
    cin >> n >> k;

    if (k == 0) {
        cout << fast_pow(k, k - 1);
        return;
    }
    if (k == 1) {
        cout << fast_pow(k, k);
        return;
    }

    for (int i = 0; i < n; ++i) {
        perm[i] = (i64)i * k % n;
    }

    i64 answer = 1;
    for (int i = 0; i < n; ++i) {
        if (!marked[i]) {
            marked[i] = true;
            int j = perm[i];
            int cycle_len = 1;
            while (!marked[j]) {
                marked[j] = true;
                j = perm[j];
                ++cycle_len;
            }
            if (custom_pow(k, cycle_len, n) == 1) {
                answer = (answer * n) % MOD;
            }
        }
    }
    cout << answer;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

#ifdef _DEBUG_
    freopen("in.txt", "r", stdin);
#endif

    run();

#ifdef _LOCAL_
    // cerr << "Time: " << fixed << setprecision(3) << (double)clock() / CLOCKS_PER_SEC << "s\n";
#endif
    return 0;
}
